import{z as s,x as A,o as t,c as d,q as n,j as B,D as l,d as e,s as o,S as i,b as E}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"部署后监控","description":"","frontmatter":{"title":"部署后监控","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/deployment-monitoring.md","filePath":"llm/deployment-monitoring.md","lastUpdated":1791063341000}'),p={name:"llm/deployment-monitoring.md"};function m(h,a,c,f,D,_){const r=A("Mermaid");return t(),d("div",null,[a[2]||(a[2]=n('<h1 id="部署后监控" tabindex="-1">部署后监控 <a class="header-anchor" href="#部署后监控" aria-label="Permalink to &quot;部署后监控&quot;">​</a></h1><div class="epigraph"><p>上线之后分布会变：用户、工具、对手、模型自己的级联。评测集停在发版日；监控必须在流量上继续抽样。</p><footer>—— 对照产品安全运营与模型漂移监测；政策框见 [RSP](/llm/safety-levels-rsp)</footer></div><p><a href="/llm/safety-levels-rsp">上一课</a>把门槛写在发版前。本课是补层「对齐理论与失效」的收束：部署后监控——在真实流量上抽检滥用、越狱、幻觉、提取迹象与能力漂移。缺口不是再做一次 Arena，而是承认发版评测的支持与线上支持不同。下一课程检索与嵌入不再默认「对齐已经结束」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>发版用固定提示集。线上会出现新工具、新越狱文风、新的级联代理、新的版权投诉。若只靠内容过滤器的精确率，会漏掉 <a href="/llm/indirect-injection">间接注入</a> 与缓慢的奖励黑客（用户用产品指标当 RM）。缺口是闭环：抽样、标注或分类器、升级、是否触发 RSP 再评测。</p><p><span class="marginnote">发版评测像出厂质检，线上监控像装了烟雾报警器：质检通过不代表永远不会着火——用户、对手和模型自己的级联每天都在改变「火源分布」。报警器的作用不是预防起火，而是起火时能叫人，这正是「闭环」两个字的含义。</span></p><p><span class="marginnote">监控可以是隐私敏感的。设计应默认最小化内容留存、聚合优先、人工抽检有权限边界。本课不写如何大规模存储用户对话。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>最小闭环：风险分层抽样（工具调用、长上下文、新用户、高权限连接加权）；自动分类器只做分流，人类看边界；仪表：越狱命中、拒答漂移、提取性重复查询、水印检测、<a href="/llm/hallucination-taxonomy">幻觉</a> 分列投诉。发现能力带可疑上升：回到危险能力评测，而不是只加一条过滤规则。发现提取：结合指纹与风控，而不是公开对质细节。</p><p><span class="marginnote">「速率与分位」翻译一下：不要因为「截图里有一条越狱成功」就改策略，那是奇闻；要看「本月一万次抽样里越狱命中率从 0.3% 升到 2%」，那才是速率。分位则看尾部——第 99 百分位的响应延迟或危害程度，而不是平均值。</span></p>',10)),(t(),B(i,null,{default:l(()=>[o(r,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20TRAF%5B%22%E7%BA%BF%E4%B8%8A%E6%B5%81%E9%87%8F%22%5D%20--%3E%20SAMP%5B%22%E5%88%86%E5%B1%82%E6%8A%BD%E6%A0%B7%22%5D%0A%20%20SAMP%20--%3E%20CLS%5B%22%E5%88%86%E7%B1%BB%20%2F%20%E4%BA%BA%E5%AE%A1%22%5D%0A%20%20CLS%20--%3E%20FIX%5B%22%E8%BF%87%E6%BB%A4%E5%99%A8%20%2F%20%E7%AD%96%E7%95%A5%22%5D%0A%20%20CLS%20--%3E%20RE%5B%22%E8%A7%A6%E5%8F%91%E5%86%8D%E8%AF%84%E6%B5%8B%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,[e("分布漂移使发版 RM 与安全分类器过时，与训练期 "),E("a",{href:"/llm/reward-hacking-llm"},"过优化"),e(" 同构，只是优化器换成了用户与对手。监控的统计对象是"),E("strong",null,"速率与分位"),e("，不是单条奇闻。没有持有标注流，分类器会自己漂移——需要定期校准集。")],-1)),(t(),B(i,null,{default:l(()=>[o(r,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E7%94%A8%E6%88%B7%E4%B8%8E%E5%AF%B9%E6%89%8B%E9%80%82%E5%BA%94%E7%8E%B0%E8%A1%8C%E8%BF%87%E6%BB%A4%E5%99%A8%22%5D%20--%3E%20B%5B%22%E7%BA%BF%E4%B8%8A%E5%88%86%E5%B8%83%E6%8C%81%E7%BB%AD%E6%BC%82%E7%A7%BB%22%5D%0A%20%20B%20--%3E%20C%5B%22%E9%83%A8%E7%BD%B2%E6%97%B6%E7%9A%84%20RM%20%2F%20%E5%AE%89%E5%85%A8%E5%88%86%E7%B1%BB%E5%99%A8%E8%BF%87%E6%97%B6%22%5D%0A%20%20C%20--%3E%20D%5B%22%E6%BC%8F%E6%A3%80%E7%8E%87%E7%BC%93%E6%85%A2%E4%B8%8A%E5%8D%87%3Cbr%2F%3E%E5%8D%95%E6%9D%A1%E5%A5%87%E9%97%BB%E7%9C%8B%E4%B8%8D%E5%87%BA%E8%B6%8B%E5%8A%BF%22%5D%0A%20%20D%20--%3E%20E%5B%22%E7%94%A8%E6%96%B0%E6%A0%87%E6%B3%A8%E6%B5%81%E5%AE%9A%E6%9C%9F%E6%A0%A1%E5%87%86%E5%88%86%E7%B1%BB%E5%99%A8%22%5D%0A%20%20E%20--%3E%7C%E6%9B%B4%E6%96%B0%E5%90%8E%E5%86%8D%E4%B8%8A%E7%BA%BF%7C%20A%0A"})]),fallback:l(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=n('<p><span class="marginnote">「分布漂移」就是「用户和世界变了，模型还停在原地」：训练时分类器见的是标注团队写的提示，上线后见的是真人、脚本和故意绕路的攻击者。分类器本身也是模型，输入变了它的准确率就会悄悄下滑——所以校准集要像电池一样定期换。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不提供监控用户的隐蔽手段，不提供绕过产品安全的流量特征。对齐补层在此结束；检索课从嵌入训练另起，默认你已知道：上线后 \\(R^*\\) 仍要被测量。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>部署后监控补发版评测的分布缺口。</li><li>闭环：抽样 → 分流 → 修复或再评测。</li><li>能力带可疑上升走 RSP，不只加过滤器。</li><li>出处：RSP 课；线上安全运营常识；奖励黑客与注入课。</li></ul>',5))])}const F=s(p,[["render",m]]);export{C as __pageData,F as default};
